1|//! Multi-project state for the desktop app.
2|//!
3|//! The desktop shows every project the user has touched — both folders they
4|//! explicitly added and projects discovered from the shared session store — and
5|//! lists each project's sessions. It reuses the CLI's on-disk configuration
6|//! (`config.json`, `auth.json`, `settings.json`) and session tree, so the two
7|//! front-ends see the same data.
8|
9|use anyhow::{Context, Result};
10|use oxide_core::config::Config;
11|use oxide_core::session::{SessionLog, SessionSummary};
12|use oxide_core::trust::{DefaultTrust, TrustStore};
13|use serde::{Deserialize, Serialize};
14|use std::path::{Path, PathBuf};
15|use std::time::{SystemTime, UNIX_EPOCH};
16|
17|/// A folder the user added to the desktop, persisted across launches.
18|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
19|pub struct Project {
20|    /// Stable identity: the canonical project path.
21|    pub id: String,
22|    pub path: PathBuf,
23|    pub name: String,
24|    #[serde(default)]
25|    pub added_at: u64,
26|    #[serde(default, skip_serializing_if = "Option::is_none")]
27|    pub last_opened_at: Option<u64>,
28|}
29|
30|/// A project as rendered in the sidebar: registered folders plus folders
31|/// discovered from sessions, annotated with activity.
32|#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
33|pub struct ProjectView {
34|    /// Stable identity for the row: the canonical path for a registered folder,
35|    /// the session `cwd` for a discovered one. The UI needs it to remove a
36|    /// project and to select the one that was just added.
37|    pub id: String,
38|    pub path: String,
39|    pub name: String,
40|    /// Whether the folder was explicitly added (vs. only seen in a session).
41|    pub registered: bool,
42|    pub exists: bool,
43|    pub session_count: usize,
44|    pub last_session_at: u64,
45|    pub last_opened_at: Option<u64>,
46|}
47|
48|#[derive(Debug, Clone, Default, Serialize, Deserialize)]
49|pub struct ProjectRegistry {
50|    pub projects: Vec<Project>,
51|}
52|
53|/// How a project's local resources (agents, commands, skills, plugins, MCP)
54|/// are treated, mirroring the CLI's `trust.json` resolution.
55|#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
56|pub struct ProjectTrust {
57|    /// The project has resources that can execute or reshape the agent.
58|    pub required: bool,
59|    /// Those resources are currently loaded.
60|    pub trusted: bool,
61|    /// Nothing is saved and the default is `ask`, so the desktop should prompt
62|    /// before loading project resources.
63|    pub awaiting: bool,
64|    /// The configured fallback (`ask` / `always` / `never`).
65|    pub default: String,
66|    /// The gated resources, for the prompt.
67|    pub resources: Vec<String>,
68|}
