70|impl ProjectRegistry {
71|    pub fn load_from(path: &Path) -> Result<Self> {
72|        match std::fs::read_to_string(path) {
73|            Ok(text) => serde_json::from_str(&text)
74|                .with_context(|| format!("parsing desktop projects at {}", path.display())),
75|            Err(err) if err.kind() == std::io::ErrorKind::NotFound => Ok(Self::default()),
76|            Err(err) => Err(err).with_context(|| format!("reading {}", path.display())),
77|        }
78|    }
79|
80|    pub fn save_to(&self, path: &Path) -> Result<()> {
81|        if let Some(parent) = path.parent() {
82|            std::fs::create_dir_all(parent)
83|                .with_context(|| format!("creating {}", parent.display()))?;
84|        }
85|        let text = serde_json::to_string_pretty(self)?;
86|        let tmp = path.with_extension("json.tmp");
87|        std::fs::write(&tmp, text).with_context(|| format!("writing {}", tmp.display()))?;
88|        std::fs::rename(&tmp, path).with_context(|| format!("replacing {}", path.display()))?;
89|        Ok(())
90|    }
91|}
