101|impl DesktopManager {
102|    /// Loads the registry from `<config>/Oxide/desktop/projects.json`, sharing
103|    /// the Oxide config directory with the CLI.
104|    pub fn load() -> Result<Self> {
105|        Self::load_from(default_store_path()?)
106|    }
107|
108|    pub fn load_from(store: PathBuf) -> Result<Self> {
109|        let registry = ProjectRegistry::load_from(&store)?;
110|        Ok(Self { registry, store })
111|    }
112|
113|    pub fn store_path(&self) -> &Path {
114|        &self.store
115|    }
116|
117|    pub fn registered(&self) -> &[Project] {
118|        &self.registry.projects
119|    }
120|
121|    fn persist(&self) -> Result<()> {
122|        self.registry.save_to(&self.store)
123|    }
124|
125|    /// Adds a folder, canonicalizing it so the same project added twice (or via
126|    /// a symlink) resolves to one entry.
127|    pub fn add_project(&mut self, path: &Path) -> Result<Project> {
128|        let canonical = path
129|            .canonicalize()
130|            .with_context(|| format!("resolving {}", path.display()))?;
131|        if !canonical.is_dir() {
132|            anyhow::bail!("{} is not a directory", canonical.display());
133|        }
134|        if let Some(existing) = self
135|            .registry
136|            .projects
137|            .iter_mut()
138|            .find(|project| project.path == canonical)
139|        {
140|            existing.last_opened_at = Some(now_secs());
141|            let found = existing.clone();
142|            self.persist()?;
143|            return Ok(found);
144|        }
145|        let project = Project {
146|            id: canonical.to_string_lossy().to_string(),
147|            name: display_name(&canonical),
148|            path: canonical,
149|            added_at: now_secs(),
150|            last_opened_at: Some(now_secs()),
151|        };
152|        self.registry.projects.push(project.clone());
153|        self.persist()?;
154|        Ok(project)
155|    }
156|
157|    /// Removes a folder from the sidebar. Sessions on disk are left untouched.
158|    pub fn remove_project(&mut self, id: &str) -> Result<bool> {
159|        let before = self.registry.projects.len();
160|        self.registry
161|            .projects
162|            .retain(|project| project.id != id && project.path.to_string_lossy() != id);
163|        let removed = self.registry.projects.len() != before;
164|        if removed {
165|            self.persist()?;
166|        }
167|        Ok(removed)
168|    }
169|
170|    /// Records that a project was just opened.
171|    pub fn touch(&mut self, id: &str) -> Result<()> {
172|        if let Some(project) = self
173|            .registry
174|            .projects
175|            .iter_mut()
176|            .find(|project| project.id == id)
177|        {
178|            project.last_opened_at = Some(now_secs());
179|            self.persist()?;
180|        }
181|        Ok(())
182|    }
183|
184|    /// Sessions for one project, newest first.
185|    pub fn sessions_for(&self, project: &Path) -> Result<Vec<SessionSummary>> {
186|        SessionLog::list(project)
187|    }
188|
189|    /// Every session across every project, newest first.
190|    pub fn all_sessions(&self) -> Result<Vec<SessionSummary>> {
191|        SessionLog::list_all()
192|    }
193|
194|    /// The CLI configuration for a project: the same global `config.json` and
195|    /// `auth.json`, with that project's ecosystem loaded and project trust
196|    /// resolved exactly as the CLI does before running.
197|    pub fn config_for(&self, project: &Path) -> Result<Config> {
198|        load_project_config(project)
199|    }
200|
201|    /// Reads the shared session store and merges it with the registry.
202|    pub fn overview(&self) -> Result<Vec<ProjectView>> {
203|        Ok(self.overview_with(&self.all_sessions()?))
204|    }
205|
206|    /// Pure merge of registered projects and session-derived projects. Kept
207|    /// separate from disk I/O so it can be tested directly.
208|    pub fn overview_with(&self, sessions: &[SessionSummary]) -> Vec<ProjectView> {
209|        let mut views: Vec<ProjectView> = Vec::new();
210|
211|        for project in &self.registry.projects {
212|            let path = project.path.to_string_lossy().to_string();
213|            let (count, last) = session_stats(sessions, &project.path);
214|            views.push(ProjectView {
215|                id: project.id.clone(),
216|                exists: project.path.is_dir(),
217|                path,
218|                name: project.name.clone(),
219|                registered: true,
220|                session_count: count,
221|                last_session_at: last,
222|                last_opened_at: project.last_opened_at,
223|            });
224|        }
225|
226|        for summary in sessions {
227|            let path = PathBuf::from(&summary.cwd);
228|            if views.iter().any(|view| view.path == summary.cwd) {
229|                continue;
230|            }
231|            // One row per distinct session cwd not already registered.
232|            let (count, last) = session_stats(sessions, &path);
233|            views.push(ProjectView {
234|                id: summary.cwd.clone(),
235|                exists: path.is_dir(),
236|                name: display_name(&path),
237|                path: summary.cwd.clone(),
238|                registered: false,
239|                session_count: count,
240|                last_session_at: last,
241|                last_opened_at: None,
242|            });
243|        }
