64|/// Media the message carried, so a reopened thread can still preview it instead
65|/// of reducing it to the `[image]` marker in `content`.
66|fn message_attachments(message: &Message) -> Vec<Value> {
67|    let Some(MessageContent::Parts(parts)) = &message.content else {
68|        return Vec::new();
69|    };
70|    parts
71|        .iter()
72|        .filter_map(|part| match part {
73|            ContentPart::ImageUrl { image_url } => Some(json!({
74|                "name": "image",
75|                "dataUrl": image_url.url,
76|            })),
77|            ContentPart::File { file } => Some(json!({
78|                "name": file.filename.clone().unwrap_or_else(|| "document".into()),
79|                "dataUrl": file.file_data,
80|            })),
81|            ContentPart::Text { .. } => None,
82|        })
83|        .collect()
