52|function formatTime(secs) {
53|  if (!secs) return "";
54|  const date = new Date(secs * 1000);
55|  const diff = Date.now() - date.getTime();
56|  const mins = Math.round(diff / 60000);
57|  if (mins < 1) return "just now";
58|  if (mins < 60) return `${mins}m ago`;
59|  const hours = Math.round(mins / 60);
60|  if (hours < 24) return `${hours}h ago`;
61|  const days = Math.round(hours / 24);
62|  if (days < 30) return `${days}d ago`;
63|  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
